label): ?><label class="check"><input type="checkbox" name="<?= $k ?>" value="1" <?= ($v[$k]??($k==='hierarchical'?0:1))?'checked':'' ?>><?= $label ?></label><?php endforeach ?><p class="hint">کلید پایدار خودکار است. نوع انتخاب و محل ذخیره محور دارای مقدار، بدون بررسی اطلاعات تغییر نمی‌کند. محور جدید هیچ پرونده‌ای را خودکار به مقادیرش نسبت نمی‌دهد.</p><button class="primary">ذخیره محور</button></form></details><?php endif ?>
