000"><?= e(isset($old['aliases'])?$old['aliases']:implode("\n",Protocol::decode($v['aliases']??'[]'))) ?></textarea></label></div><?php if(in_array($axis,['occupation','employment_state'],true)): ?><input type="hidden" name="military_trigger_present" value="1"><label class="check"><input type="checkbox" name="military_trigger" value="1" <?= !empty($old['military_trigger'])||(!$old&&!empty(Protocol::decode($v['metadata']??'{}')['military_trigger']))?'checked':'' ?>>این مقدار، اطلاعات تکمیلی نظامی را در فرم شهید فعال کند</label><?php endif ?><label class="check"><input type="checkbox" name="active" value="1" <?= ($v['active']??1)?'checked':'' ?>>فعال</label><p class="hint">حذف مخرب مقدار استفاده‌شده ارائه نمی‌شود. غیرفعال‌کردن، رابطه‌های قبلی را نگه می‌دارد. نامک داخلی هنگام تغییر عنوان ثابت می‌ماند.</p><button class="primary">ذخیره مقدار</button></form>
<?php if(!$geographic): ?><details class="panel"><summary>ادغام کنترل‌شده دو مقدار هم‌معنا</summary><form method="post" class="community-form"><?= Security::field() ?><input type="hidden" name="action" value="martyr-term-merge"><input type="hidden" name="taxonomy" value="<?= e($axis) ?>"><div class="fields"><label>مقدار مبدأ<select name="source_id"><?php foreach($parents as $p): ?><option value="<?= $p['id'] ?>"><?= e($p['title']) ?></option><?php endforeach ?></select></label><label>مقدار مقصد<select name="target_id"><?php foreach($parents as $p): ?><option value="<?= $p['id'] ?>"><?= e($p['title']) ?></option><?php endforeach ?></select></label></div><label>دلیل ادغام<textarea name="reason" required maxlength="2000"></textarea></label><p class="hint">تعداد شهدای مرتبط هر مقدار در جدول بالاست. روابط اولیه، متن‌ها و سابقه‌ها حفظ می‌شوند؛ فیلتر عمومی هر دو مقدار را معادل مقصد می‌خواند. نوع محور تغییر نمی‌کند.</p><label class="check"><input type="checkbox" name="merge_ack" value="1" required> هم‌معنابودن دو مقدار و تعداد روابط را بررسی کرده‌ام.</label><button class="primary">ثبت نگاشت ادغام</button></form></details><?php foreach($redirects as $r): ?><form method="post" class="panel community-form"><?= Security::field() ?><input type="hidden" name="action" value="martyr-term-undo"><input type="hidden" name="taxonomy" value="<?= e($axis) ?>"><input type="hidden" name="source_id" value="<?= $r['source_term_id'] ?>"><p><?= e($r['source_title']) ?> ← <?= e($r['target_title']) ?></p><label>دلیل لغو نگاشت<input name="reason" required maxlength="2000"></label><label class="check"><input type="checkbox" name="undo_ack" value="1" required> نگاشت لغو شود؛ انتخاب‌های تازه مقصد تغییر نکنند.</label><button class="outline">لغو نگاشت ادغام</button></form><?php endforeach ?><?php endif ?>
